import type { FieldDefinition } from './field-definition-model';
import type { Request } from './request-model';
import type { Person } from './person-model';
import type { Workspace } from './workspace-model';

export interface RequestAttachment {
  /**
   * @displayName Request Attachment ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName FileName
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  fileName: string;
  /**
   * @displayName ContentType
   * @validationRule Required for create/update operations
   */
  contentType: string;
  /**
   * @displayName CreatedAt
   * @validationRule Required for create/update operations
   */
  createdAt: string;
  /**
   * @displayName Field Definition
   */
  fieldDefinition?: Pick<FieldDefinition, 'id' | 'label'>;
  /**
   * @displayName FileSizeBytes
   * @validationRule Required for create/update operations
   */
  fileSizeBytes: number;
  /**
   * @displayName Is Deleted
   */
  isDeleted?: boolean;
  /**
   * @displayName RequestId
   * @validationRule Required for create/update operations
   */
  requestId: Pick<Request, 'id' | 'requestNumber'>;
  /**
   * @displayName Stable Field Key
   */
  stableFieldKey?: string;
  /**
   * @displayName UploadedBy
   * @validationRule Required for create/update operations
   */
  uploadedBy: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName WorkspaceId
   * @validationRule Required for create/update operations
   */
  workspaceId: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _RequestAttachment = 'RequestAttachment' as const;